<script setup>
import {FilePenLine} from '@lucide/vue'
import { inject, ref, computed, watch } from 'vue'
import { api } from '../api'
import { formatDate } from '../utils/assignments'
import QuizAnswerReview from './QuizAnswerReview.vue'
const selectedCourse=inject('selectedCourse',null)
const props = defineProps({ assignment: Object, submissionId: String, staff: Boolean })
const emit = defineEmits(['changed'])
const snapshots = ref([]), rubric = ref(null), grades = ref([]), selected = ref(''), before = ref(''), error = ref(''), notice = ref(''), busy = ref(false), loading = ref(false)
const gradeLoading = ref(false), quiz=ref(null), essays=ref({})
const score = ref(0), feedback = ref(''), levels = ref({})
const current = computed(() => snapshots.value.find(s => s.id === selected.value))
const previous = computed(() => snapshots.value.find(s => s.id === before.value))
const calculated = computed(() => quiz.value ? quiz.value.objectiveScore+Object.values(essays.value).reduce((a,b)=>a+Number(b||0),0) : !rubric.value ? Number(score.value) : Math.round(rubric.value.criteria.reduce((n, c) => n + c.weight * Number(levels.value[c.id] || 0), 0) / (rubric.value.criteria.reduce((n, c) => n + c.weight, 0) * 4) * props.assignment.maxScore * 100) / 100)
const essayMarks=computed(()=>quiz.value?.marks.filter(m=>m.questionType==='essay')||[])
const pendingInput=computed(()=>essayMarks.value.filter(m=>essays.value[m.questionId]==null || essays.value[m.questionId]==='').length)
const edited=computed(()=>feedback.value!==(grades.value[0]?.feedback||'') || essayMarks.value.some(m=>String(essays.value[m.questionId]??'')!==String(grades.value[0]?.essayScores?.[m.questionId]??'')))
async function confirmQuiz(){
 if(busy.value||gradeLoading.value||pendingInput.value)return
 if(essayMarks.value.some(m=>!Number.isFinite(Number(essays.value[m.questionId]))||Number(essays.value[m.questionId])<0||Number(essays.value[m.questionId])>m.points)){error.value='請填寫各申論題配分範圍內的分數。';return}
 if(!confirm(`確認總分 ${calculated.value} / ${props.assignment.maxScore}？確認後寫入正式成績簿並對學生發布。`))return
 busy.value=true;error.value='';notice.value=''
 try{
  let grade=grades.value[0]
  if(essayMarks.value.length && (!grade||edited.value))grade=await api(`/assignments/${props.assignment.id}/revisions/${selected.value}/grades`,{method:'POST',body:{expectedGradeId:grade?.id||null,score:calculated.value,feedback:feedback.value,criteria:[],essayScores:Object.fromEntries(essayMarks.value.map(m=>[m.questionId,Number(essays.value[m.questionId])]))}})
  await api(`/assignments/${props.assignment.id}/revisions/${selected.value}/grades/${grade.id}/release`,{method:'POST'})
  await loadGrades();notice.value='教師已確認，正式成績簿已更新。';emit('changed')
 }catch(e){error.value=e.message}finally{busy.value=false}
}
async function loadGrades() { if (!selected.value) return; const id = selected.value; gradeLoading.value = true; grades.value = []; quiz.value = null; essays.value = {}; score.value = 0; feedback.value = ''; levels.value = {}; try { const result = await api(`/assignments/${props.assignment.id}/revisions/${id}/grades`); if (id !== selected.value) return; quiz.value=props.assignment.isQuiz?await api(`/assignments/${props.assignment.id}/revisions/${id}/quiz-grading`):null;if(!quiz.value?.marks)quiz.value=null;if(id!==selected.value)return;grades.value = result; const g = grades.value[0]; essays.value={...(g?.essayScores||{})};score.value = g?.score || 0; feedback.value = g?.feedback || ''; levels.value = Object.fromEntries(g?.criteria.map(c => [c.criterionId, c.level]) || []) } finally { if (id === selected.value) gradeLoading.value = false } }
async function load() { loading.value = true; error.value = ''; try { [snapshots.value, rubric.value] = await Promise.all([api(`/assignments/${props.assignment.id}/submissions/${props.submissionId}/revisions`), api(`/assignments/${props.assignment.id}/rubric`)]); selected.value = snapshots.value[0]?.id || ''; before.value = snapshots.value[1]?.id || ''; await loadGrades() } catch (e) { error.value = e.message } finally { loading.value = false } }
watch(() => props.submissionId, load, { immediate: true })
async function select() { error.value = ''; notice.value = ''; try { await loadGrades() } catch (e) { error.value = e.message } }
async function save() { if (gradeLoading.value) return; busy.value = true; error.value = ''; notice.value = ''; try { await api(`/assignments/${props.assignment.id}/revisions/${selected.value}/grades`, { method: 'POST', body: { expectedGradeId: grades.value[0]?.id || null, score: calculated.value, feedback: feedback.value, essayScores:quiz.value?Object.fromEntries(quiz.value.marks.filter(m=>m.questionType==='essay').map(m=>[m.questionId,Number(essays.value[m.questionId])])):{}, criteria: rubric.value?.criteria.map(c => ({ criterionId: c.id, level: Number(levels.value[c.id]) })) || [] } }); await loadGrades(); notice.value = '人工評分草稿已儲存，尚未發布。'; emit('changed') } catch (e) { error.value = e.message } finally { busy.value = false } }
async function release() { if (gradeLoading.value) return; if (!window.confirm('確定發布此版本的分數與回饋給學生？')) return; busy.value = true; error.value = ''; try { await api(`/assignments/${props.assignment.id}/revisions/${selected.value}/grades/${grades.value[0].id}/release`, { method: 'POST' }); await loadGrades(); notice.value = '回饋已發布。'; emit('changed') } catch (e) { error.value = e.message } finally { busy.value = false } }
function text(snapshot, question) { return snapshot?.answers.find(a => a.questionId === question)?.text || '' }
</script>
<template><section class="surface form-surface teaching-panel"><h2><FilePenLine v-if="staff" :size="20" /> {{staff?'作業評閱與給分':'提交紀錄與教師回饋'}}</h2><p v-if="loading">載入提交版本中…</p><p v-if="error" class="error-box" role="alert">{{ error }}</p><p v-if="notice" class="success-box" role="status">{{ notice }}</p><p v-if="!loading && !snapshots.length" class="empty-inline">尚無正式提交版本。</p><template v-if="snapshots.length"><div class="form-grid"><label>檢視版本<select v-model="selected" :disabled="busy" @change="select"><option v-for="s in snapshots" :key="s.id" :value="s.id">第 {{ s.revisionNo }} 次提交 · {{ formatDate(s.submittedAt) }}</option></select></label><label>對照版本<select v-model="before"><option value="">不比較</option><option v-for="s in snapshots" :key="s.id" :value="s.id">第 {{ s.revisionNo }} 次提交</option></select></label></div><p v-if="current" class="muted">此學生的提交紀錄 · {{ formatDate(current.submittedAt) }}。評分只適用於此提交版本，新版本須另行評閱。</p><div v-for="q in assignment.questions" :key="q.id"><h3>題目 {{ q.sortOrder }}</h3><p class="question-prompt">{{q.promptText}}</p><p v-if="staff && q.gradingGuidance" class="studio-prose submission-notice">教師評分參考：{{q.gradingGuidance}}</p><div class="revision-comparison" :class="{ paired: previous }"><article v-if="previous"><h4>對照：第 {{ previous.revisionNo }} 次</h4><QuizAnswerReview :question="q" :text="text(previous,q.id)" :show-key="staff" /></article><article><h4>檢視：第 {{ current?.revisionNo }} 次</h4><QuizAnswerReview :question="q" :text="text(current,q.id)" :show-key="staff" :mark="gradeLoading ? null : quiz?.marks.find(m=>m.questionId===q.id)" :essay-score="gradeLoading ? undefined : grades[0]?.essayScores?.[q.id]" /></article></div></div><p v-if="quiz" class="submission-notice">客觀題已自動批改（多選全對得分）{{quiz.objectiveScore==null?'，成績待發布':'，客觀題得分：'+quiz.objectiveScore}}；{{quiz.pendingEssays?'申論題待教師評分：'+quiz.pendingEssays+' 題':'全部題目已評分'}}。</p><div v-if="quiz && quiz.objectiveScore!=null" class="table-scroll"><table class="data-table"><thead><tr><th>客觀題</th><th>結果</th><th>得分／配分</th></tr></thead><tbody><tr v-for="mark in quiz.marks.filter(m=>m.questionType!=='essay')" :key="mark.questionId"><td>題目 {{assignment.questions.find(q=>q.id===mark.questionId)?.sortOrder}}</td><td>{{mark.correct?'答對':'答錯／未答'}}</td><td>{{mark.autoScore}} / {{mark.points}}</td></tr></tbody></table></div><section v-if="staff && !selectedCourse?.taRestrictions?.includes('grading') && quiz" class="submission-notice" aria-live="polite"><strong>即時暫算：{{calculated}} / {{assignment.maxScore}}</strong><p>{{pendingInput?'尚有 '+pendingInput+' 題申論待評，以上為已評分小計。':'所有題目已評分；確認前不寫入正式成績簿。'}}</p><button v-if="!grades[0]?.releasedAt || edited" class="button primary" :disabled="busy || gradeLoading || pendingInput>0" @click="confirmQuiz">確認成績並寫入正式成績簿</button></section><template v-if="staff && !selectedCourse?.taRestrictions?.includes('grading') && (!quiz || quiz.marks.some(m=>m.questionType==='essay'))"><form @submit.prevent="save"><fieldset :disabled="busy || gradeLoading || loading"><h3>人工評分 · 滿分 {{ assignment.maxScore }}</h3><template v-if="quiz"><label v-for="(mark,index) in quiz.marks.filter(m=>m.questionType==='essay')" :key="mark.questionId">申論題 {{assignment.questions.find(q=>q.id===mark.questionId)?.sortOrder}} 得分／{{mark.points}}<input aria-label="人工分數" v-model.number="essays[mark.questionId]" type="number" min="0" :max="mark.points" step="0.01" required /></label><p>客觀題自動得分 {{quiz.objectiveScore}} ＋申論得分＝{{calculated}} / {{assignment.maxScore}}</p></template><template v-else-if="rubric"><h4>{{ rubric.title }} · v{{ rubric.versionNo }}</h4><label v-for="c in rubric.criteria" :key="c.id">{{ c.title }}（權重 {{ c.weight }}）<span class="muted">{{ c.description }}</span><select v-model.number="levels[c.id]" required><option disabled :value="undefined">選擇級別</option><option v-for="(description, i) in c.levels" :key="i" :value="i + 1">{{ i + 1 }}：{{ description }}</option></select></label><p>加權總分：{{ calculated }} / {{ assignment.maxScore }}</p></template><label v-else>人工分數<input v-model.number="score" type="number" min="0" :max="assignment.maxScore" step="0.01" required /></label><label>教師回饋<textarea v-model="feedback" rows="5" maxlength="16000"></textarea></label><div class="form-bottom"><button type="submit" class="button primary">儲存評分草稿</button><button v-if="!quiz && grades[0] && !grades[0].releasedAt" type="button" class="button secondary" @click="release">發布回饋</button></div></fieldset></form></template><h3>{{ staff ? '評分變更歷程' : '已發布的教師評閱' }}</h3><p v-if="!grades.length" class="empty-inline">{{ staff ? '此版本尚未評分。' : '此版本尚無已發布回饋。' }}</p><article v-for="g in grades" :key="g.id" class="question-editor"><strong>{{g.graderUserId?'評分':'系統自動評分'}} {{ g.score }} / {{ assignment.maxScore }} · {{ g.releasedAt ? '已發布' : '草稿' }}</strong><p>{{ g.feedback }}</p><p class="muted">{{ g.graderName }} · 評分 {{ formatDate(g.gradedAt) }}<template v-if="g.releasedAt"> · 發布 {{ formatDate(g.releasedAt) }}</template></p></article></template></section></template>
